// src/pages/StagesInformation.jsx
import React, { useEffect, useState } from "react";
import NavBar from "../NavBar.jsx";
import BottomNav from "../components/BottomNav.jsx";
import PreflightStepper from "../components/preflight/PreflightStepper.jsx";

const StagesInformation = () => {
  const [showNexusInfo, setShowNexusInfo] = useState(false);

  // progress for Nexus card pills (also read from localStorage on load)
  const [micOk, setMicOk] = useState(false);
  const [videoOk, setVideoOk] = useState(false);
  const [signalOk, setSignalOk] = useState(false);
  const [preflightKey, setPreflightKey] = useState(0); // force remount of stepper after reset

  // auto-unlock Challenge when Nexus interview completes
  const [challengeUnlocked, setChallengeUnlocked] = useState(
    typeof window !== "undefined" && localStorage.getItem("nexusCompleted") === "true"

    
  );

  useEffect(() => {
    // hydrate pills from persisted state
    const m = localStorage.getItem("preflight.micOk") === "true";
    const v = localStorage.getItem("preflight.videoOk") === "true";
    const s = localStorage.getItem("preflight.signalOk") === "true";
    setMicOk(m); setVideoOk(v); setSignalOk(s);

    const check = () => setChallengeUnlocked(localStorage.getItem("nexusCompleted") === "true");
    const onStorage = (e) => { if (e.key === "nexusCompleted") check(); };
    const onVis = () => { if (!document.hidden) check(); };
    window.addEventListener("storage", onStorage);
    document.addEventListener("visibilitychange", onVis);

    return () => {
      window.removeEventListener("storage", onStorage);
      document.removeEventListener("visibilitychange", onVis);
    };
  
  }, []);

  // Reset helper: clears preflight flags and remounts the stepper
  const restartPreflight = () => {
    try {
      localStorage.removeItem("preflight.micOk");
      localStorage.removeItem("preflight.videoOk");
      localStorage.removeItem("preflight.signalOk");
    } catch {}
    setMicOk(false); setVideoOk(false); setSignalOk(false);
    setPreflightKey(k => k + 1); // remount PreflightStepper so it starts from Mic
  };

  const toggleNexusInfo = () => {
    setShowNexusInfo((v) => {
      const next = !v;
      if (next) {
        // Always start fresh when opening Nexus
     restartPreflight();
      }
      return next;
    });
  };
  const onKeyToggle = (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      toggleNexusInfo();
    }
  };

  const handleProgress = ({ micOk, videoOk, signalOk }) => {
    setMicOk(!!micOk);
    setVideoOk(!!videoOk);
    setSignalOk(!!signalOk);
  };

  const allGood = micOk && videoOk && signalOk;

  return (
    <div className="min-h-screen bg-gray-800 text-white">
      <NavBar onSignIn={() => {}} onSignUp={() => {}} />

      <main className="max-w-6xl mx-auto px-6 pt-24 pb-28">
        <header className="text-center mb-10">
          <h1 className="text-3xl md:text-4xl font-bold">Stages Information</h1>
          <p className="text-gray-300 mt-2">
            Begin with <span className="text-green-300 font-semibold">Nexus</span>. Other stages unlock as you progress.
          </p>
        </header>

        {/* 3 Cards */}
        <section className="grid grid-cols-1 md:grid-cols-3 gap-6 relative">
          {/* Nexus (active) */}
          <div
            role="button"
            tabIndex={0}
            aria-expanded={showNexusInfo}
            onClick={toggleNexusInfo}
            onKeyDown={onKeyToggle}
            className="relative p-10 rounded-2xl bg-white/5 border border-white/10 shadow-xl hover:shadow-2xl transition transform hover:-translate-y-0.5 focus:outline-none focus:ring-2 focus:ring-green-400 glow-card"
          >
            <h2 className="text-2xl font-semibold text-center text-green-300 select-none">Nexus</h2>

            

            {/* progress pills */}
            

            <span className="sr-only">Click to view Nexus details below</span>
          </div>

          {/* Challenge (locked/unlocked) */}
          {challengeUnlocked ? (
            <div
              className="relative p-10 rounded-2xl bg-white/5 border border-white/10 shadow-xl hover:shadow-2xl transition"
              role="button"
              tabIndex={0}
              onClick={() => alert("Challenge stage content coming soon.")}
            >
              <h2 className="text-2xl font-semibold text-center text-green-300 select-none">Challenge</h2>
              <div className="absolute top-3 right-3 px-2 py-0.5 rounded-full text-[11px] bg-green-400 text-gray-900">Unlocked ✓</div>
            </div>
          ) : (
            <div className="relative group p-10 rounded-2xl bg-white/5 border border-white/10 shadow-xl cursor-not-allowed">
              <h2 className="text-2xl font-semibold text-center text-gray-300 select-none">Challenge</h2>
              <div role="tooltip" className="pointer-events-none absolute -top-3 left-1/2 -translate-x-1/2 -translate-y-full bg-gray-900 text-white text-xs rounded px-3 py-1 opacity-0 group-hover:opacity-100 transition duration-200">
                Complete the Nexus stage to unlock the Challenge stage.
                <span className="absolute left-1/2 -translate-x-1/2 top-full w-3 h-3 bg-gray-900 rotate-45"></span>
              </div>
            </div>
          )}

          {/* Perform (locked) */}
          <div className="relative group p-10 rounded-2xl bg-white/5 border border-white/10 shadow-xl cursor-not-allowed">
            <h2 className="text-2xl font-semibold text-center text-gray-300 select-none">Perform</h2>
            <div role="tooltip" className="pointer-events-none absolute -top-3 left-1/2 -translate-x-1/2 -translate-y-full bg-gray-900 text-white text-xs rounded px-3 py-1 opacity-0 group-hover:opacity-100 transition duration-200">
              Complete the Challenge stage to unlock the Perform stage.
              <span className="absolute left-1/2 -translate-x-1/2 top-full w-3 h-3 bg-gray-900 rotate-45"></span>
            </div>
          </div>
        </section>

        {/* Nexus Details Card (appears after click) */}
        {showNexusInfo && (
          <section className="relative mt-8">
            {/* Pointer triangle */}
            <div className="mx-auto md:ml-0 md:w-1/3 mb-3 flex justify-center md:justify-start">
              <div className="w-0 h-0 border-l-8 border-r-8 border-b-[12px] border-l-transparent border-r-transparent border-b-white/20"></div>
            </div>

            <div className="relative rounded-2xl bg-white/10 border border-white/15 shadow-2xl p-6 backdrop-blur">
              <h3 className="text-2xl font-semibold text-green-300 mb-4">Nexus — Stage Overview</h3>

              <ul className="space-y-2 text-gray-200 leading-relaxed">
                <li><span className="font-medium text-white">Nexus stage duration:</span> 25 minutes</li>
                <li><span className="font-medium text-white">Total no. of questions:</span> 8</li>
                <li><span className="font-medium text-white">Rapid Fire (bonus):</span> Optional — skip if unnecessary</li>
                <li><span className="font-medium text-white">Total points:</span> 1000</li>
              </ul>

              <div className="mt-5">
                <h4 className="font-semibold text-white mb-2">Score → Outcome</h4>
                <div className="overflow-hidden rounded-xl border border-white/10">
                  <table className="w-full text-sm">
                    <thead className="bg-white/10">
                      <tr className="text-left"><th className="px-4 py-2">Range</th><th className="px-4 py-2">Badge</th></tr>
                    </thead>
                    <tbody className="divide-y divide-white/10">
                      <tr><td className="px-4 py-2 text-gray-200">0 – 350</td><td className="px-4 py-2">Fail</td></tr>
                      <tr><td className="px-4 py-2 text-gray-200">350 – 550</td><td className="px-4 py-2">Bronze</td></tr>
                      <tr><td className="px-4 py-2 text-gray-200">550 – 750</td><td className="px-4 py-2">Silver</td></tr>
                      <tr><td className="px-4 py-2 text-gray-200">750 – 900</td><td className="px-4 py-2">Gold</td></tr>
                      <tr><td className="px-4 py-2 text-gray-200">900 – 1000</td><td className="px-4 py-2">Masterpiece</td></tr>
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Preflight checks (emits progress up) */}
              <div className="mt-6">
                <h4 className="font-semibold text-white mb-2">Before you begin</h4>
                <p className="text-gray-300 mb-3">We’ll check your microphone, camera, and network signal.</p>
                <PreflightStepper key={preflightKey} onProgress={handleProgress} />
              </div>
            </div>
          </section>
        )}
      </main>

      <BottomNav />

      <style>{`
        @keyframes glowPulse {
          0%   { box-shadow: 0 0 0px 0 rgba(74, 222, 128, 0.45); }
          50%  { box-shadow: 0 0 28px 8px rgba(74, 222, 128, 0.85); }
          100% { box-shadow: 0 0 0px 0 rgba(74, 222, 128, 0.45); }
        }
        .glow-card {
          border-color: rgba(74, 222, 128, 0.55);
          animation: glowPulse 2.4s ease-in-out infinite;
        }
      `}</style>
    </div>
  );
};

export default StagesInformation;
