import React, { useEffect, useMemo, useRef, useState } from "react";
import { useNavigate } from "react-router-dom";

import MicTest from "./MicTest.jsx";
import VideoTest from "./VideoTest.jsx";
import SignalTest from "./SignalTest.jsx";
import ConsentModal from "./ConsentModal.jsx";
import Countdown from "./Countdown.jsx";

/**
 * PreflightStepper
 * Drives the sequence: Mic -> Video -> Signal -> Consent -> Countdown -> Interview.
 * Persist flags in localStorage: preflight.micOk, preflight.videoOk, preflight.signalOk
 *
 * Props:
 *  - onProgress?: ({ micOk:boolean, videoOk:boolean, signalOk:boolean }) => void
 */
export default function PreflightStepper({ onProgress }) {
  const navigate = useNavigate();

  // persist keys
  const LS_MIC = "preflight.micOk";
  const LS_VIDEO = "preflight.videoOk";
  const LS_SIGNAL = "preflight.signalOk";

  // UI state
  const [micOk, setMicOk] = useState(false);
  const [videoOk, setVideoOk] = useState(false);
  const [signalOk, setSignalOk] = useState(false);

  // flow state
  const [step, setStep] = useState("mic"); // 'mic' | 'video' | 'signal' | 'consent' | 'countdown'
  const [consentOpen, setConsentOpen] = useState(false);
  const [showCountdown, setShowCountdown] = useState(false);

  // countdown + nav control
  const COUNT_SECONDS = 5;
  const navigatedRef = useRef(false);

  // Load persisted flags once, pick first incomplete step
  useEffect(() => {
    const m = localStorage.getItem(LS_MIC) === "true";
    const v = localStorage.getItem(LS_VIDEO) === "true";
    const s = localStorage.getItem(LS_SIGNAL) === "true";
    setMicOk(m);
    setVideoOk(v);
    setSignalOk(s);

    if (!m) setStep("mic");
    else if (!v) setStep("video");
    else if (!s) setStep("signal");
    else {
      setStep("consent");
      setConsentOpen(true);
    }
  }, []);

  // Report progress to parent when flags change
  useEffect(() => {
    onProgress?.({ micOk, videoOk, signalOk });
  }, [micOk, videoOk, signalOk, onProgress]);

  // Countdown fallback navigation (bulletproof hand-off)
  useEffect(() => {
    if (!showCountdown) return;
    const t = setTimeout(() => {
      if (!navigatedRef.current) {
        navigatedRef.current = true;
        navigate("/interview");
      }
    }, COUNT_SECONDS * 1000 + 220);
    return () => clearTimeout(t);
  }, [showCountdown, navigate]);

  // Handlers for each step
  const handleMicPass = () => {
    setMicOk(true);
    localStorage.setItem(LS_MIC, "true");
    setStep("video");
  };

  const handleVideoPass = () => {
    setVideoOk(true);
    localStorage.setItem(LS_VIDEO, "true");
    setStep("signal");
  };

  const handleSignalPass = () => {
    setSignalOk(true);
    localStorage.setItem(LS_SIGNAL, "true");
    setStep("consent");
    setConsentOpen(true);
  };

  // Consent decision -> start countdown
  const handleConsentChoice = () => {
    setConsentOpen(false);
    setShowCountdown(true);
    setStep("countdown");
  };

  // Countdown finished -> navigate (primary path; fallback also exists)
  const handleCountdownDone = () => {
    if (!navigatedRef.current) {
      navigatedRef.current = true;
      navigate("/interview");
    }
  };

  // Simple step header (optional visual)
  const StepBadge = ({ active, done, label }) => (
    <div
      className={[
        "px-2.5 py-1 rounded-md text-xs font-medium border",
        active ? "bg-white/10 border-white/20 text-white" :
        done ? "bg-green-500/15 border-green-400/40 text-green-300" :
               "bg-white/5 border-white/10 text-white/70"
      ].join(" ")}
    >
      {label}
    </div>
  );

  return (
    <div className="rounded-xl border border-white/10 bg-white/5 p-4">
      {/* Tiny stepbar */}
      <div className="flex flex-wrap items-center gap-2 mb-4">
        <StepBadge active={step === "mic"}     done={micOk}    label="Mic Test" />
        <span className="text-white/40">→</span>
        <StepBadge active={step === "video"}   done={videoOk}  label="Video Test" />
        <span className="text-white/40">→</span>
        <StepBadge active={step === "signal"}  done={signalOk} label="Signal Test" />
        <span className="text-white/40">→</span>
        <StepBadge active={step === "consent" || step === "countdown"} done={false} label="Consent" />
      </div>

      {/* Body */}
      {step === "mic" && (
        <MicTest onPass={handleMicPass} />
      )}

      {step === "video" && (
        <VideoTest onPass={handleVideoPass} />
      )}

      {step === "signal" && (
        <SignalTest onPass={handleSignalPass} />
      )}

      {/* Consent modal sits on top when open */}
      {consentOpen && (
        <ConsentModal
          open={consentOpen}
          onCancel={() => setConsentOpen(false)}
          onChoice={handleConsentChoice}
        />
      )}

      {/* Fullscreen countdown overlay + primary callback */}
      {showCountdown && (
        <Countdown seconds={COUNT_SECONDS} onDone={handleCountdownDone} />
      )}
    </div>
  );
}
