import React, { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
// If Countdown.jsx sits next to ConsentModal.jsx, this path is correct.
// Otherwise adjust (e.g., "../preflight/Countdown.jsx").
import Countdown from "./Countdown.jsx";

/**
 * ConsentModal — quick reconfirmation before starting interview recording.
 *
 * Writes to localStorage:
 *  recording.consent -> "true" | "false"
 *  recording.mode    -> "video_audio" | "audio_only" | "text_only"
 *  recording.meta    -> JSON payload
 */
export default function ConsentModal({ open, onChoice, onCancel }) {
  const COUNT_SECONDS = 5; // keep in sync with Countdown
  const [mode, setMode] = useState("video_audio");
  const [ack, setAck] = useState(false);
  const [showMore, setShowMore] = useState(false);
  const [counting, setCounting] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    if (!open) return;
    try {
      const last = localStorage.getItem("recording.mode");
      if (last === "video_audio" || last === "audio_only" || last === "text_only") {
        setMode(last);
      }
    } catch {}
    setAck(false);
    setShowMore(false);
  }, [open]);

  const language = useMemo(() => {
    try {
      const meta = JSON.parse(localStorage.getItem("recording.meta") || "{}");
      return meta.language || "en";
    } catch {
      return "en";
    }
  }, [open]);

  // Navigate to InterviewRoom as soon as countdown ends
  const goInterview = () => {
    navigate("/interview", { replace: true, state: { mode } });
  };

  const handleContinue = () => {
    const payload = {
      consent_given: mode !== "text_only",
      mode,
      consent_date: new Date().toISOString(),
      language,
      source: "preflight",
    };
    localStorage.setItem("recording.consent", payload.consent_given ? "true" : "false");
    localStorage.setItem("recording.mode", mode);
    localStorage.setItem("recording.meta", JSON.stringify(payload));
    try { onChoice?.(payload); } catch { onChoice?.(); }

    // Start the countdown overlay; when it reaches 0, goInterview will fire.
    setCounting(true);
  };

  // 🔒 Fallback navigator: even if something re-renders, we still navigate after the countdown budget.
  useEffect(() => {
    if (!counting) return;
    const t = setTimeout(goInterview, COUNT_SECONDS * 1000 + 220);
    return () => clearTimeout(t);
  }, [counting, COUNT_SECONDS]); // `goInterview` is stable enough for a one-shot
  // When counting, show only the countdown overlay (so it sits on top cleanly)
  if (counting) {
    // By default Countdown uses 5 seconds; pass `seconds={3}` if you prefer 3s.
    return <Countdown seconds={COUNT_SECONDS} onDone={goInterview} />;
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div role="dialog" aria-modal="true" aria-labelledby="consent-title"
           className="w-full max-w-xl rounded-2xl bg-gray-900 border border-white/10 p-6 shadow-2xl">
        <div className="flex items-start justify-between gap-3">
          <h3 id="consent-title" className="text-xl font-semibold text-white">Recording Consent (Quick Confirm)</h3>
          <button onClick={onCancel} aria-label="Close" className="text-white/60 hover:text-white rounded-md px-2 py-1">✕</button>
        </div>

        <p className="text-gray-200 mt-3">
          We’d like to record your interview to provide <span className="font-semibold">Guided Video Replay</span>.
          By default, the recording is stored <span className="font-semibold">only on your device</span> and is
          deleted after 7 days (or sooner if you delete it).
        </p>

        <ul className="list-disc pl-5 text-gray-200 mt-3 space-y-1">
          <li>What we record: your audio, video, and on-screen responses (depending on your choice).</li>
          <li>No cloud upload unless you explicitly opt in later.</li>
          <li>You can view or delete your recording in the Feedback screen.</li>
        </ul>

        <div className="mt-4 text-white/90 font-medium">Choose how to proceed:</div>
        <div className="mt-2 grid grid-cols-1 sm:grid-cols-3 gap-2">
          <label className={`p-3 rounded-lg border cursor-pointer ${mode==="video_audio"?"border-green-400/60 bg-green-500/10":"border-white/15 bg-white/5"}`}>
            <input type="radio" name="mode" className="hidden" checked={mode==="video_audio"} onChange={()=>setMode("video_audio")} />
            Video + Audio
          </label>
          <label className={`p-3 rounded-lg border cursor-pointer ${mode==="audio_only"?"border-green-400/60 bg-green-500/10":"border-white/15 bg-white/5"}`}>
            <input type="radio" name="mode" className="hidden" checked={mode==="audio_only"} onChange={()=>setMode("audio_only")} />
            Audio-only
          </label>
          <label className={`p-3 rounded-lg border cursor-pointer ${mode==="text_only"?"border-amber-400/60 bg-amber-500/10":"border-white/15 bg-white/5"}`}>
            <input type="radio" name="mode" className="hidden" checked={mode==="text_only"} onChange={()=>setMode("text_only")} />
            No recording (text feedback)
          </label>
        </div>

        <label className="flex items-center gap-2 mt-4 text-gray-200">
          <input type="checkbox" className="accent-green-400 w-4 h-4" checked={ack} onChange={(e)=>setAck(e.target.checked)} />
          <span>I understand the recording policy.</span>
        </label>

        <button onClick={()=>setShowMore(s=>!s)} className="mt-3 text-sm text-white/70 underline underline-offset-4">
          Learn more
        </button>
        {showMore && (
          <div className="mt-2 text-sm text-gray-300 bg-white/5 border border-white/10 rounded-lg p-3">
            We record directly in your browser using WebRTC/MediaRecorder and store the file in IndexedDB.
            Nothing is uploaded to our servers unless you later choose to save it. You can verify storage in
            your browser’s Application panel and delete recordings anytime in Feedback.
          </div>
        )}

        <div className="mt-6 flex justify-end gap-3">
          <button onClick={onCancel} className="px-4 py-2 rounded-lg bg-white/10 border border-white/15 hover:bg-white/20">Cancel</button>
          <button onClick={handleContinue} disabled={!ack}
                  className={`px-4 py-2 rounded-lg font-semibold shadow focus:outline-none focus:ring-2
                    ${ack ? "bg-green-400 text-gray-900 hover:bg-green-300 focus:ring-green-300"
                          : "bg-white/10 text-white/60 border border-white/15 cursor-not-allowed"}`}>
            Continue
          </button>
        </div>
      </div>
    </div>
  );
}
