import React, { useEffect, useState } from "react";

export default function Countdown({ seconds = 5, onDone }) {
  const [n, setN] = useState(seconds);
  const [blackout, setBlackout] = useState(false);
  useEffect(() => {
    const t = setInterval(() => setN((x) => x - 1), 1000);
    return () => clearInterval(t);
  }, []);
  useEffect(() => {
    if (n <= 0 && !blackout) {
      setBlackout(true); // go fully black first
      const t = setTimeout(() => onDone?.(), 180); // then navigate
      return () => clearTimeout(t);
    }
  }, [n, blackout, onDone]);

  return (
    <div className={`fixed inset-0 z-40 flex items-center justify-center
                    ${blackout ? "bg-black" : "bg-black/60"} transition-colors duration-200`}>
       <div className="rounded-2xl bg-gray-900 border border-white/10 px-10 py-8 text-center shadow-2xl">
         <div className="text-gray-300 mb-2">You’re going to attend the mock interview.</div>
         <div className="text-6xl font-bold text-green-300 animate-pulse">{Math.max(0, n)}</div>
       </div>
     </div>
   );
 }
