import React, { useEffect, useRef, useState } from "react";

/**
 * SignalTest (with timed progress + multi-sample check)
 * - Shows a short animated test (≈1–2s) instead of instant pass.
 * - Measures:
 *    • navigator.connection (if available): rtt/downlink/effectiveType
 *    • 3× pings to same-origin (cache-busted) for avg RTT + jitter
 * - Pass when:
 *    • avgRTT <= 200 ms, AND
 *    • downlink >= 2 Mbps if available, AND
 *    • effectiveType ∈ {4g, 5g, unknown}
 * - Shows "Continue" button to advance only after user sees results.
 */
export default function SignalTest({ onPass }) {
  const [phase, setPhase] = useState("idle"); // idle | testing | result
  const [progress, setProgress] = useState(0);
  const [ok, setOk] = useState(false);
  const [netInfo, setNetInfo] = useState({ rtt: null, downlink: null, effectiveType: "unknown" });
  const [rtts, setRtts] = useState([]);
  const [avgRtt, setAvgRtt] = useState(null);
  const [jitter, setJitter] = useState(null);
  const timerRef = useRef(null);

  useEffect(() => () => { if (timerRef.current) clearInterval(timerRef.current); }, []);

  const softProgress = (target, speed = 10) => {
    // Smoothly animate progress up to `target`
    return new Promise((resolve) => {
      const int = setInterval(() => {
        setProgress((p) => {
          const next = Math.min(target, p + speed);
          if (next >= target) {
            clearInterval(int);
            resolve();
          }
          return next;
        });
      }, 30);
      timerRef.current = int;
    });
  };

  const pingOnce = async (url, timeoutMs = 2500) => {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), timeoutMs);
    const t0 = performance.now();
    try {
      await fetch(url, { cache: "no-store", signal: ctrl.signal });
      return performance.now() - t0;
    } catch {
      return timeoutMs; // treat abort/failure as slow
    } finally {
      clearTimeout(t);
    }
  };

  const test = async () => {
    setPhase("testing");
    setProgress(0);
    setOk(false);
    setRtts([]);
    setAvgRtt(null);
    setJitter(null);

    // Phase 1: read Network Information API
    const c = navigator.connection || navigator.webkitConnection || navigator.mozConnection;
    const info = {
      rtt: c?.rtt ?? null,
      downlink: c?.downlink ?? null,
      effectiveType: c?.effectiveType ?? "unknown",
    };
    setNetInfo(info);
    await softProgress(20);

    // Phase 2: 3× pings (same-origin; cache-busted)
    const targets = [
      `${location.origin}/favicon.ico?ts=${Date.now()}`,
      `${location.origin}/?ts=${Date.now() + 1}`,
      `${location.origin}/?ts=${Date.now() + 2}`,
    ];

    const samples = [];
    for (let i = 0; i < targets.length; i++) {
      const ms = await pingOnce(targets[i]);
      samples.push(ms);
      setRtts([...samples]);
      await softProgress(20 + (i + 1) * 20);
    }

    const avg = Math.round(samples.reduce((a, b) => a + b, 0) / samples.length);
    const jit = Math.round(
      samples
        .map((s) => Math.abs(s - avg))
        .reduce((a, b) => a + b, 0) / samples.length
    );
    setAvgRtt(avg);
    setJitter(jit);

    // Phase 3: decide pass/fail (allow unknown fields)
    const rttOK = avg <= 200;
    const downOK = info.downlink == null ? true : info.downlink >= 2;
    const typeOK = ["4g", "5g", "unknown"].includes(info.effectiveType || "unknown");
    const pass = rttOK && downOK && typeOK;

    setOk(pass);
    await softProgress(95);
    await softProgress(100);
    setPhase("result");
  };

  const retry = () => {
    setPhase("idle");
    setProgress(0);
    setOk(false);
    setNetInfo({ rtt: null, downlink: null, effectiveType: "unknown" });
    setRtts([]);
    setAvgRtt(null);
    setJitter(null);
  };

  return (
    <div className="rounded-xl border border-white/10 p-4 bg-white/5">
      <h4 className="font-semibold text-white mb-2">Signal Quality Check</h4>

      {phase === "idle" && (
        <button
          onClick={test}
          className="px-4 py-2 rounded-lg bg-green-400 text-gray-900 font-semibold shadow hover:bg-green-300 focus:outline-none focus:ring-2 focus:ring-green-300"
        >
          Test Your Signal
        </button>
      )}

      {phase === "testing" && (
        <div className="space-y-3">
          <div className="text-gray-200">Testing your signal…</div>
          <div className="w-full h-2 rounded-full bg-white/10 overflow-hidden">
            <div
              className="h-2 bg-green-400 transition-all"
              style={{ width: `${progress}%` }}
            />
          </div>
          <div className="text-xs text-gray-400">Collecting RTT samples and network info…</div>
        </div>
      )}

      {phase === "result" && (
        <>
          <div className="text-sm text-gray-300">
            Avg RTT: <span className="text-white">{avgRtt ?? "n/a"}</span> ms &middot; Jitter:{" "}
            <span className="text-white">{jitter ?? "n/a"}</span> ms &middot; Downlink:{" "}
            <span className="text-white">{netInfo.downlink ?? "n/a"}</span> Mbps &middot; Type:{" "}
            <span className="text-white">{netInfo.effectiveType}</span>
          </div>

          {ok ? (
            <div className="mt-3 flex items-center justify-between">
              <div className="flex items-center gap-2 text-green-300 font-semibold">
                <span className="inline-block w-2 h-2 rounded-full bg-green-400 animate-pulse" />
                Signal looks good.
              </div>
              <button
                onClick={() => onPass?.()}
                className="px-4 py-2 rounded-lg bg-green-400 text-gray-900 font-semibold shadow hover:bg-green-300 focus:outline-none focus:ring-2 focus:ring-green-300"
              >
                Continue
              </button>
            </div>
          ) : (
            <>
              <ul className="mt-3 text-sm text-gray-300 list-disc pl-5 space-y-1">
                <li>Move closer to your Wi-Fi router or switch to a stable network.</li>
                <li>Close heavy downloads/streams and other tabs using camera/mic.</li>
                <li>If on mobile data, prefer strong 4G/5G.</li>
              </ul>
              <button
                onClick={retry}
                className="mt-3 px-4 py-2 rounded-lg bg-white/10 border border-white/15 hover:bg-white/20"
              >
                Test Again
              </button>
            </>
          )}
        </>
      )}
    </div>
  );
}
