import React, { useEffect, useRef, useState } from "react";

/**
 * VideoTest (strict gating + unlatch on degrade)
 * - CTA appears ONLY while Resolution, Brightness & Face are good.
 * - If brightness/face/resolution fails after passing, CTA hides again.
 * - Adds explicit "Face not detected" warning.
 * - Stability uses good/ bad streak timers to avoid flicker.
 */
export default function VideoTest({ onBegin, onPass }) {
  const [started, setStarted] = useState(false);
  const [error, setError] = useState("");

  // UI states (display only)
  const [brightness, setBrightness] = useState(null);
  const [resolution, setResolution] = useState(null);
  const [faceOk, setFaceOk] = useState(false);
  const [ready, setReady] = useState(false);
  const [goodMsUI, setGoodMsUI] = useState(0);

  // Refs for RAF timing (avoid stale closures)
  const lastTsRef = useRef(null);
  const goodMsRef = useRef(0);
  const badMsRef  = useRef(0);
  const readyRef  = useRef(false);

  const videoRef = useRef(null);
  const drawRef = useRef(null);    // overlay canvas
  const sampleRef = useRef(null);  // tiny canvas for analysis
  const streamRef = useRef(null);
  const tickRef = useRef(null);
  const detectorRef = useRef(null);

  // Gates / thresholds
  const GOOD_STREAK_MS = 1500;          // ~1.5s steady before allowing CTA
  const BAD_CLEAR_MS   = 300;           // ~0.3s bad -> hide CTA to avoid instant flicker
  const MIN_W = 640, MIN_H = 480;       // resolution gate
  const MIN_B = 120, MAX_B = 190;       // brightness gate

  const stop = () => {
    if (tickRef.current) cancelAnimationFrame(tickRef.current);
    if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
    streamRef.current = null;
  };
  useEffect(() => () => stop(), []);

  const ensureDetector = () => {
    if ("FaceDetector" in window) {
      try { detectorRef.current = new window.FaceDetector({ fastMode: true, maxDetectedFaces: 1 }); } catch {}
    }
  };

  const drawOverlay = (boxes, w, h) => {
    const c = drawRef.current;
    if (!c) return;
    c.width = w; c.height = h;
    const ctx = c.getContext("2d");
    ctx.clearRect(0, 0, w, h);
    if (boxes && boxes.length) {
      ctx.lineWidth = 3;
      ctx.strokeStyle = "rgba(74, 222, 128, 0.95)";
      boxes.forEach(b => ctx.strokeRect(b.x, b.y, b.width, b.height));
    } else {
      // fallback guide box (center)
      const gw = Math.round(w * 0.4), gh = Math.round(h * 0.5);
      const gx = Math.round((w - gw) / 2), gy = Math.round((h - gh) / 2);
      ctx.lineWidth = 2;
      ctx.strokeStyle = "rgba(255,255,255,0.4)";
      ctx.setLineDash([6, 6]);
      ctx.strokeRect(gx, gy, gw, gh);
      ctx.setLineDash([]);
    }
  };

  const skinHeuristicOk = (v) => {
    // Analyze center ROI for skin-like pixels
    const s = sampleRef.current;
    if (!s) return false;
    const w = v.videoWidth, h = v.videoHeight;
    if (!w || !h) return false;

    const roiW = Math.round(w * 0.4);
    const roiH = Math.round(h * 0.5);
    const roiX = Math.round((w - roiW) / 2);
    const roiY = Math.round((h - roiH) / 2);

    s.width = 160; s.height = Math.round(160 * (roiH / roiW));
    const ctx = s.getContext("2d", { willReadFrequently: true });
    ctx.drawImage(v, roiX, roiY, roiW, roiH, 0, 0, s.width, s.height);
    const data = ctx.getImageData(0, 0, s.width, s.height).data;

    let skin = 0, total = data.length / 4;
    for (let i = 0; i < data.length; i += 4) {
      const R = data[i], G = data[i + 1], B = data[i + 2];
      const Y  =  0.299*R + 0.587*G + 0.114*B;
      const Cb = -0.168736*R - 0.331264*G + 0.5*B + 128;
      const Cr =  0.5*R - 0.418688*G - 0.081312*B + 128;
      if (Y > 30 && Cb > 77 && Cb < 127 && Cr > 133 && Cr < 173) skin++;
    }
    const ratio = skin / total;
    return ratio > 0.12; // ~12% of center ROI looks like skin
  };

  const measure = async (ts) => {
    const v = videoRef.current;
    const ol = drawRef.current;
    const sm = sampleRef.current;
    if (!v || !ol || !sm) { tickRef.current = requestAnimationFrame(measure); return; }

    const w = v.videoWidth, h = v.videoHeight;
    if (!w || !h) { tickRef.current = requestAnimationFrame(measure); return; }
    setResolution(`${w}×${h}`);
    const goodRes = w >= MIN_W && h >= MIN_H;

    // brightness (current frame)
    const ctxS = sm.getContext("2d", { willReadFrequently: true });
    sm.width = 160; sm.height = Math.round(160 * (h / w));
    ctxS.drawImage(v, 0, 0, sm.width, sm.height);
    const d = ctxS.getImageData(0, 0, sm.width, sm.height).data;
    let sum = 0;
    for (let i = 0; i < d.length; i += 4) sum += 0.2126 * d[i] + 0.7152 * d[i+1] + 0.0722 * d[i+2];
    const brightnessNow = Math.round(sum / (d.length / 4));
    setBrightness(brightnessNow);
    const goodLight = brightnessNow >= MIN_B && brightnessNow <= MAX_B;

    // face (detector or fallback)
    let faceBoxes = [];
    let hasFace = false;
    if (detectorRef.current) {
      try {
        const faces = await detectorRef.current.detect(v);
        if (faces && faces.length) { faceBoxes = faces.map(f => f.boundingBox); hasFace = true; }
      } catch {/* ignore */}
    }
    if (!hasFace) hasFace = skinHeuristicOk(v);
    setFaceOk(hasFace);
    drawOverlay(faceBoxes, w, h);

    // streak timing with refs (not state)
    const goodNow = goodRes && goodLight && hasFace;
    const now  = typeof ts === "number" ? ts : performance.now();
    const last = lastTsRef.current ?? now;
    const delta = Math.max(0, now - last);
    lastTsRef.current = now;

    if (goodNow) {
      goodMsRef.current = Math.min(goodMsRef.current + delta, GOOD_STREAK_MS);
      badMsRef.current  = 0;
    } else {
      badMsRef.current  = Math.min(badMsRef.current + delta, BAD_CLEAR_MS);
      goodMsRef.current = 0;
    }
    setGoodMsUI(goodMsRef.current);

    // latch ON after good streak…
    if (goodMsRef.current >= GOOD_STREAK_MS && !readyRef.current) {
      readyRef.current = true;
      setReady(true);
    }
    // …and unlatch if quality drops for a short while
    if (!goodNow && readyRef.current && badMsRef.current >= BAD_CLEAR_MS) {
      readyRef.current = false;
      setReady(false);
    }

    tickRef.current = requestAnimationFrame(measure);
  };

  const start = async () => {
    try { onBegin?.(); } catch {}
    localStorage.setItem("preflight.videoOk", "false");

    // reset timers/flags
    lastTsRef.current = null;
    goodMsRef.current = 0;
    badMsRef.current  = 0;
    readyRef.current  = false;
    setGoodMsUI(0);
    setReady(false);

    setError("");
    setBrightness(null);
    setResolution(null);
    setFaceOk(false);
    setStarted(true);
    if (!detectorRef.current) ensureDetector();

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user", width: { ideal: 1280 }, height: { ideal: 720 } }
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        await videoRef.current.play();
        tickRef.current = requestAnimationFrame(measure);
      }
    } catch (e) {
      setError("Camera access was denied or not found.");
      setStarted(false);
    }
  };

  const continueAfterReady = () => {
    stop();
    onPass?.();
  };

  const retry = () => {
    stop();
    setStarted(false);
    setError("");
    setBrightness(null);
    setResolution(null);
    setFaceOk(false);
    lastTsRef.current = null;
    goodMsRef.current = 0;
    badMsRef.current  = 0;
    readyRef.current  = false;
    setGoodMsUI(0);
    setReady(false);
  };

  // UI derivations
  const goodResUI = (() => {
    if (!resolution) return false;
    const [wStr, hStr] = resolution.split("×"); const w = +wStr, h = +hStr;
    return w >= MIN_W && h >= MIN_H;
  })();
  const goodLightUI = brightness !== null && brightness >= MIN_B && brightness <= MAX_B;
  const allChecksPassUI = goodResUI && goodLightUI && faceOk;

  // states for buttons
  const verifying = allChecksPassUI && !ready;
  const showCTA   = ready && allChecksPassUI; // <-- ONLY while all checks are currently good

  return (
    <div className="rounded-xl border border-white/10 p-4 bg-white/5">
      <h4 className="font-semibold text-white mb-2">Video Quality Check</h4>

      {!started && (
        <button
          onClick={start}
          className="px-4 py-2 rounded-lg bg-green-400 text-gray-900 font-semibold shadow hover:bg-green-300 focus:outline-none focus:ring-2 focus:ring-green-300"
        >
          Test Video Quality
        </button>
      )}

      {started && (
        <div className="space-y-3">
          <div className="relative">
            <video ref={videoRef} className="w-full rounded-lg border border-white/10" muted playsInline />
            <canvas ref={drawRef} className="absolute inset-0 w-full h-full pointer-events-none" />
          </div>

          <canvas ref={sampleRef} className="hidden" />

          {/* Requirement checklist */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-2 text-sm">
            <div className={goodResUI ? "text-green-300" : "text-red-300"}>
              Resolution ≥ {MIN_W}×{MIN_H} {goodResUI ? "✓" : (resolution ? `✗ (${resolution})` : "…")}
            </div>
            <div className={goodLightUI ? "text-green-300" : "text-red-300"}>
              Brightness {MIN_B}–{MAX_B} {goodLightUI ? "✓" : (brightness !== null ? `✗ (${brightness})` : "…")}
            </div>
            <div className={faceOk ? "text-green-300" : "text-red-300"}>
              Face visible {faceOk ? "✓" : "✗"}
            </div>
          </div>

          {/* Inline warnings */}
          {!goodLightUI && brightness !== null && (
            <div className="text-amber-300 text-sm">
              {brightness < MIN_B ? "Lighting is low. " : "Lighting is too bright. "}
              Increase/adjust your lighting so your face is evenly lit (avoid strong backlight).
              Try moving closer to a light, facing a window, or lowering screen brightness if it’s blowing out your face.
            </div>
          )}
          {!faceOk && (
            <div className="text-amber-300 text-sm">
              Face not detected. Center your full face inside the box and keep eyes visible.
            </div>
          )}

          {/* Stability bar */}
          <div className="text-xs text-gray-400">
            Stability: {Math.min(100, Math.round((goodMsUI / GOOD_STREAK_MS) * 100))}%
          </div>

          <ul className="text-sm text-gray-300 list-disc pl-5 space-y-1">
            <li>Center your full face inside the box. Keep eyes visible.</li>
            <li>Improve lighting from the front; avoid bright windows behind you.</li>
            <li>Wipe the camera lens for clarity.</li>
          </ul>

          {/* CTAs */}
          {!showCTA && !verifying && (
            <button onClick={retry} className="px-4 py-2 rounded-lg bg-white/10 border border-white/15 hover:bg-white/20">
              Test Video Again
            </button>
          )}

          {verifying && (
            <button
              className="px-4 py-2 rounded-lg bg-white/10 border border-white/15 opacity-70 cursor-not-allowed"
              disabled
              title="Hold steady while we verify video quality"
            >
              Hold steady… verifying ({Math.min(100, Math.round((goodMsUI / GOOD_STREAK_MS) * 100))}%)
            </button>
          )}

          {showCTA && (
            <div className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-2 text-green-300 font-semibold">
                <span className="inline-block w-2 h-2 rounded-full bg-green-400 animate-pulse" />
                Video looks good.
              </div>
              <button
                onClick={continueAfterReady}
                className="px-4 py-2 rounded-lg bg-green-400 text-gray-900 font-semibold shadow hover:bg-green-300 focus:outline-none focus:ring-2 focus:ring-green-300"
              >
                Video Quality Checked — Start Signal Test
              </button>
            </div>
          )}
        </div>
      )}

      {error && <div className="mt-3 text-red-300">{error}</div>}
    </div>
  );
}
